  it('reuses static validators across ten calls and caches dynamic ones by schema', async () => {
    const registry = new ToolRegistry();
    let staticSchemaReads = 0;
    registry.register(
      {
        name: 'convert_units',
        description: 'Converts measurement units',
        get inputSchema(): Record<string, unknown> {
          staticSchemaReads += 1;
          return {
            type: 'object',
            properties: {unit: {type: 'string'}},
            required: ['unit'],
          };
        },
      },
      async input => String(input.unit)
    );

    const staticResults: string[] = [];
    for (let callIndex = 0; callIndex < 10; callIndex += 1) {
      const staticReply = await registry.execute('convert_units', {unit: 'km'});
      staticResults.push(staticReply.result);
    }

    let strictSchemaReads = 0;
    const strictSchema: Record<string, unknown> = {
      type: 'object',
      get properties(): Record<string, unknown> {
        strictSchemaReads += 1;
        return {region: {type: 'string', enum: ['eu', 'us']}};
      },
      required: ['region'],
    };
    const expandedSchema: Record<string, unknown> = {
      type: 'object',
      properties: {region: {type: 'string', enum: ['eu', 'us', 'apac']}},
      required: ['region'],
    };

    let activeSchema = strictSchema;
    registry.register(
      () => ({
        name: 'deploy_service',
        description: 'Deploys to an allowed region',
        inputSchema: activeSchema,
      }),
      async input => `deployed:${String(input.region)}`
    );

    const firstStrictReply = await registry.execute('deploy_service', {region: 'apac'});
    const readsAfterFirstCompile = strictSchemaReads;
    const cachedStrictReply = await registry.execute('deploy_service', {region: 'eu'});
    activeSchema = expandedSchema;
    const expandedReply = await registry.execute('deploy_service', {region: 'apac'});
    activeSchema = strictSchema;
    const restoredStrictReply = await registry.execute('deploy_service', {region: 'apac'});

