interface StoredTool {
  resolveDefinition: () => ToolDefinition;
  resolveValidator: () => ValidateFunction;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    if (typeof definition === 'function') {
      const initial = definition();
      const toolName = initial.name;
      this.tools.set(toolName, {
        resolveDefinition: definition,
        resolveValidator: () => {
          const current = definition();
          return resolveDynamicValidator(toolName, current.inputSchema);
        },
        execute,
      });
      return;
    }
    const validateInput = compileInputSchema(definition.name, definition.inputSchema);
    this.tools.set(definition.name, {
      resolveDefinition: () => definition,
      resolveValidator: () => validateInput,
      execute,
    });
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: tool.resolveDefinition(), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => t.resolveDefinition());
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validateInput = tool.resolveValidator();
    if (!validateInput(input)) {
      const violations = formatValidationErrors(validateInput.errors);
      log.warn('tool', 'input validation failed', {name, violations});
      return {result: `Invalid input for tool "${name}": ${violations.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

const dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

function resolveDynamicValidator(toolName: string, inputSchema: Record<string, unknown>): ValidateFunction {
  const cachedValidator = dynamicValidators.get(inputSchema);
  if (cachedValidator) return cachedValidator;
  const compiledValidator = compileInputSchema(toolName, inputSchema);
  dynamicValidators.set(inputSchema, compiledValidator);
  return compiledValidator;
}

